        rules.arr.push_back(V::makeStr("Current authored opening kinds are circle, polygon, slot and window. slot uses x,y,length (overall),width,angle?; window uses x,y,width,height,angle?. Angles are degrees. sheet.opening.pattern{id,opening,count:2..32,dx,dy} creates bounded expression-driven copies and returns entity_ids. All sheet edit targets accept a unique feature name or numeric id."));
        rules.arr.push_back(V::makeStr("sheet_inspect returns bend table/allowances, panel/opening inventory, flat bounds/digest and refold evidence. export_flat_dxf writes exact analytic LINE/ARC/CIRCLE contours and BEND lines from the checked authored flat B-rep. Slot/window documents require version 17. Studio global flat layout/unbend and nominal tube stock are display-only and never replace exact export geometry."));
