    if(topic=="solids"){auto rules=*r.find("rules");rules.arr.push_back(V::makeStr("Solid normal offset: feature.add{type:native_solid,inputs:[source],native:{op:offset,join:intersection|arc},p:{distance:expression}}. Positive grows, negative shrinks; source/result require one exact valid solid. Unsupported, collapsed or invalid results reject atomically."));r.set("rules",rules);}
    if(topic=="frames"||topic=="tube"){
        r.set("stock_preview",V::makeStr("stock_preview{id,mesh?} returns nominal uncut straight stock at evaluated centerline length; only mesh:true returns vertex buffers. It does not preserve copes or certify forming."));
        r.set("trim_discovery",V::makeStr("Before trimming an existing Tube, inspect native_inspect.report.tube_end_fit_options on the source and proposed host. It exposes original cap status, straight terminal lengths, eligible lineage and bound planar host references in definition coordinates. candidate is a discovery hint, not proof of contact or fit. Use frame.trim_* on authored construction_frame members; use tube_end_fit only on eligible Tube lineage. A construction frame may contain separate member and weld solids. A single-solid Boolean cannot silently turn disconnected members into one part. If an operation reports multiple solids, read its operation name and operand census, inspect the exact inputs and change the intended operation or assembly representation; do not repeatedly retry the same command or delete solids to force success."));
    }
    if(topic=="physics"){
        r.set("tools",list({"materials_inspect","physics_inspect","doc_preview","doc_apply"}));
        r.set("inertial_simulation",V::makeStr("Run physics_inspect{expected_revision,simulation:{action:run,backend:gpu,duration_s:1,step_s:0.00416666666667,output_fps:30,bodies:[{node:123,copy:0,force_N:[0,0,0],torque_Nm:[0,0,0]}]}}. First use simulation:{action:capabilities} to verify hardware. GPU integration, convex-mesh contact impulses and unlimited revolute joints are separate from static physics. Exact CAD mass/inertia requires declared density; concave meshes and unsupported joints reject. assembly_joints:false explicitly detaches bodies. Positions/ground_z_mm are mm; forces N, torques Nm, velocity m/s, angular velocity rad/s. include_frames adds revision-bound display poses. No silent CPU fallback: backend:cpu is explicit. Inspect diagnostics, time-step convergence and joint drift; discrete collision, no FEA/CCD/qualification. Never overwrite CAD placements with display results."));
        r.set("rules",list({"Declare material density using density in g/cm3 OR density_kg_m3. Physical material properties use SI: young_modulus_Pa, poisson_ratio, yield_strength_Pa, thermal_expansion_per_K. These save version 20; zero density remains unknown.","physics_inspect returns exact mass and inertia for a local feature or visible placed instances. Frame profiles own frame mass. PCB mass requires a per-material physical BOM. Missing density never becomes partial aggregate mass.","Gravity is a uniform xyz vector in m/s2; positions are mm. Loads are force_N,point_mm,torque_Nm. Reported rigid-body energy, momentum and required wrench are instantaneous calculations, not a contact/dynamics or FEA simulation.","Support projection considers gravity only on a caller-declared simple planar polygon. axial_test uses a declared cross-section, length and modulus and excludes buckling. beam_test supports cantilever_tip or simply_supported_center with material, length_mm, second_moment_mm4, extreme_fiber_mm, force_N; optional buckling requires minimum_second_moment_mm4, area_mm2, effective_length_factor and compression_N. weld_test requires effective_throat_mm, effective_length_mm, force_N and optional allowable_stress_Pa. These are declared ideal analytical cases, not inferred geometry, frame FEA, fatigue, combined-load certification or weld qualification. Use returned design_qualified:false and limits. Keep loads/supports/material sources explicit; missing data remains unknown.","Use doc_apply checks to require mass, clearance or stability bounds before committing a design."}));
        V example;arkjson::parse(R"({"gravity":[0,0,-9.80665],"reference_point_mm":[0,0,0],"loads":[{"force_N":[0,0,100],"point_mm":[200,0,50]}]})",example);r.set("example_physics_inspect",example);
    }
    if(topic=="automation"){
        r.set("tools",list({"reference_navigate","selection_set","geometry_query","math_eval","query_batch","doc_preview","placement_plan","pattern_plan","design_solve","doc_apply"}));
        r.set("rules",list({"Inspect with query_batch or geometry_query; use semantic names, explicit units and reference frames. Every native query reports its own ok status. Batch read-only library_get/search/info/sources alongside geometry queries. query_batch fields projects existing top-level result keys; it does not create measurements. Inspect each result isError/structuredContent and the available fields named by a missing-field error, then request the actual named field or read the full result once. A query may carry an id; a later query in the same batch takes a value from that full result with {\"$ref\":\"id.path\"} in its args. paths selects nested values (key, key[n], key[a:b], key[] for each element) instead of the whole result, and max_bytes makes a larger row return its shape instead of its data. assembly_info.clearance returns separation_mm/overlap_volume_mm3 only when clearance_checked supports that request; do not project a guessed clearance key or interpret a missing value as zero.","reference_navigate{id,reference,kind:all|face|edge} discovers exact adjacent semantic references, including edges sharing vertices. selection_set{id,reference,expected_revision,instance?,copy?} applies a named face/edge in live Studio without document mutation. Standalone headless calls validate and report view_state_applied:false. Keep observed revisions and occurrence IDs; topology indices are not persistent names.","doc_preview evaluates optional checks, caches a candidate for up to 300 seconds and returns a candidate_id apply payload. doc_apply commits it without geometry recomputation, checks revision and fingerprint, and creates one undo entry. Failed required checks return POSTCONDITION_FAILED with observed residuals; geometry validity is not manufacturing certification.","placement_plan aligns frames or centroids; constrained placements use existing mates. pattern_plan modes solid/holes stay linked to the path in version 19; instances/points are snapshots.","design_solve adjusts one bounded scalar parameter and returns an apply payload only when the requested residual converges. Topology continuity and a global optimum are not certified.","Negative legacy clearance is a penetration estimate. Use separation_mm and overlap_volume_mm3 to distinguish free space from overlap; penetration_depth_checked remains false."}));
        for(const auto& tool:AgentSession::tools(true).arr)if(tool.find("name")->str=="doc_apply")r.set("command_reference",*tool.find("description"));
        V example;arkjson::parse(R"({"id":"Block","queries":[{"action":"references","filter":{"kind":"face","normal":[0,0,1]},"unique":true},{"action":"properties"}]})",example);r.set("example_geometry_query",example);
    }
    if(topic=="sketch"||topic=="surfacing"||topic=="solids"){auto rules=*r.find("rules");rules.arr.push_back(V::makeStr("046B profile regions: a sketch with several non-touching closed loops is one profile by even-odd containment (depth 0 outer, 1 hole, 2 island). native_solid extrude (distance, symmetric, direction, up_to_face), legacy extrude, extrude_surface/revolve_surface with p.solid=1 and a sweep section (p.solid=1, contact 0) build faces with holes; a hollow sweep must conserve outer-minus-holes volume. One feature publishes one solid: several regions (disjoint outer loops or islands) reject unless native.regions selects one: [{entity:outer-loop curve name}] or [{point:[x,y]}] in sketch coordinates (expressions follow parameters). Seeds on a boundary, in a hole, outside, naming a hole curve, duplicated or two per seed reject. Crossing, touching, shared-vertex, zero-area or self-intersecting loops, and open chains without a selection reject naming the entities. Hole walls are side.<entity>; the receipt profile_regions orders loops by depth then entity order. sketch_inspect reports profile_regions. Mesh revolve keeps one loop. native.regions saves format 48; multi-loop sketches without it keep their format. See PROFILE_REGIONS_046B."));r.set("rules",rules);}
    if(topic=="solids"||topic=="automation"){
        V rules=r.find("rules")?*r.find("rules"):V::makeArr();rules.arr.push_back(V::makeStr("044B curve_pattern (pattern_plan mode solid, version 47): references:[edge names] auto-chains G0-connected edges into one arc-length path (the first edge fixes direction and the closed-loop seam; reverse flips); omit reference/references to use a whole wire curve feature (sketch entity via curve op project, spatial spline, intersection curve) or a spline cable centerline. count 2..2048 or pitch_mm with pitch_mode fit|truncate; start_margin_mm/end_margin_mm; a closed loop without margins spaces count stations with no seam duplicate (phase_mm shifts station 0); skip:[station indices] keeps names stable. orientation translate|x_hint|frenet|surface; surface uses a third input or the path body faces (support_faces), project:true moves stations onto the surface with offset_mm and reports max deviation (max_deviation_mm rejects). Copies share the seed geometry; reference_scheme copies publishes copy.<station>.<name> within 512 names, compact publishes only named_copies (default the first) and keeps copy_face_stride/copy_edge_stride for @ark handles; selection inventory <= 16384. Union the pattern into a body as a boolean tool; no implicit fuse. See CURVE_PATTERNS_044B."));rules.arr.push_back(V::makeStr("Native CAD vertex pull: inspect native_inspect{id}.topology.vertices first; each exact B-rep vertex row gives name:vertex.N, point_mm and source_topology (the observed exact B-rep SHA256). Author native_solid with inputs:[that exact source ID], native:{op:vertex_pull,source_vertex:observed vertex name,source_topology:observed digest}, p:{dx,dy,dz} expression displacement in source-local mm. It retains the source and verifies one closed planar-triangle/convex-quad polyhedron; an affected nonplanar quad is explicitly faceted. Curved, holed, complex, stale-digest, self-intersecting or degenerate sources/results reject atomically. Do not substitute display mesh indices or a screenshot for exact vertex identity. Studio Pull vertex routes exact CAD and explicit mesh sources to their respective authorities."));r.set("rules",rules);
    }
    if(topic=="assembly"||topic=="automation"){
        auto rules=*r.find("rules");
        rules.arr.push_back(V::makeStr("022B component patterns use assembly.add/edit pattern:{type:linear|circular|pattern_driven|sketch_driven|curve_driven|chain,count?,source?,skips?}. Counts are expressions 2..32, copy0 always keeps the authored/solved seed pose, and skips list unique stable slots 1..31 without renumbering. One node owns rigid placements; the mate solver carries the set once while BOM counts each emitted definition/copy. New source/skips recipes require document37; ordinary legacy linear/circular recipes retain their prior format."));
        rules.arr.push_back(V::makeStr("pattern_driven source:{node:patterned occurrence id|unique name} inherits that source's resolved copy transforms and skips, including rotated groups and solved poses. sketch_driven source:{sketch:name,points:[named point entities]} uses solved point/datum geometry; alternatively source:{feature:authored spatial curve id|name,points:[start,segment.N.end,segment.N.through,actual point/pole handles]} uses real solved XYZ coordinates. Count can be omitted for these two types to follow source slots; an explicit count must match. Source names bind once to IDs; missing/suppressed sources, point deletions, ambiguous references and cyclic/self-consuming dependencies reject atomically."));
        rules.arr.push_back(V::makeStr("curve_driven source:{feature:id|name,reference:exact edge name or path,spacing:equal|pitch,pitch?:expression,margin?:expression,alignment:fixed|tangent,normal:[three expressions] for tangent,closed?:boolean,endpoint:exclude|include,max_source_error?:expression}. path traverses 1..32 connected unbranched native curve edges; mesh samples are not the source. Native arc-length queries evaluate positions/tangents, and orientation rotates about the seed origin. Fitted helix/equation sources require an explicit max_source_error in (0,1] mm covering observed checkpoints and available native fit error; no global between-checkpoint proof is inferred. Independent feature-local guides are required; assembly-dependent guides reject."));
        rules.arr.push_back(V::makeStr("For an open guide, equal spacing with endpoint include reaches the last usable station; exclude leaves that station out. Positive pitch and nonnegative end margins cannot overrun the guide. Closed paths require closed:true, zero margins and endpoint:exclude; count*pitch must close within the fixed 1e-6 mm limit. Tangent alignment uses exact station tangents and the explicit normal projected perpendicular to them; undefined tangents or parallel normal/tangent pairs reject. Source geometry uses definition coordinates in the pattern parent's frame, not a screenshot or a guessed occurrence placement."));
        rules.arr.push_back(V::makeStr("chain adds alternate_feature:id|name or alternate_node:distinct unpatterned occurrence id|name, never both, plus alternate_angle:expression. Odd slots use that second seed definition or actual relative pose and a local-X rotation (default 90 degrees for a definition, 0 for a second occurrence). Two-definition closed alternation needs even count. Pitch is distance along the guide; contact, connected-linkage articulation, chord-length fit, motion, clearance and manufacture remain unverified. Read assembly_info.diagnostics.patterns for guide length, pitch, endpoint/closure residuals, stable slots and explicit unchecked domains. Hyphenated pattern-driven/sketch-driven/curve-driven/chain-component names normalize to their canonical stored types."));
        r.set("rules",rules);r.set("component_pattern_contract",V::makeStr("docs/SPECIALIZED_PATTERNS_022B.md"));
        V example;arkjson::parse(R"({"commands":[{"op":"param.set","name":"component_pitch","expr":"15"},{"op":"feature.add","type":"box","name":"Pattern pin","p":{"dx":2,"dy":3,"dz":4}},{"op":"assembly.add","name":"Driving row","feature":"Pattern pin","pattern":{"type":"linear","count":4,"dx":"component_pitch"}},{"op":"assembly.add","name":"Driven row","feature":"Pattern pin","p":{"ty":20},"pattern":{"type":"pattern_driven","source":{"node":"Driving row"},"skips":[2]}}]})",example);example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_component_patterns",example);
    }
    if(topic=="sheet"){
        auto rules=*r.find("rules");
        rules.arr.push_back(V::makeStr("022B advanced sheet source: sheet.miter/swept_flange/corner/rip/tab add commands carry miter/swept_flange/corner/rip/tab; edit carries entity and values, remove carries entity. Targets id accept a unique feature name or numeric ID. Native lists are miters,swept_flanges,corners,rips,tabs and bend_table; they persist in document37, retain stable generated panel IDs and regenerate exact formed/flat geometry. Use current expected_revision, inspect sheet_inspect/native_inspect receipts, and preserve dependencies; failed geometry or missing IDs roll back the entire mutation."));
        rules.arr.push_back(V::makeStr("Miter flange: miter:{id,parent:original base,edges:[2..4 named base edges],gap:positive expression,profile:[{length,angle:90,inner_radius},{length,angle:-90,inner_radius}]} (inverse signed profile also supported). At least one adjacent pair is required. The common wall/outward-lip profile applies real attachment cutbacks and exact coplanar bisector trims; inspect advanced_ops gap_mm and measured_min_gap_mm. Arbitrary-angle profiles, curved perimeter paths and overlap seams are unsupported; no solids or tolerances are silently changed to make a corner succeed."));
        rules.arr.push_back(V::makeStr("Straight swept flange/contour: swept_flange:{id,parent,edge,width?,offset?,path:straight_edge,profile:[1..8 {length,angle,inner_radius,k_factor?}]} sweeps a constant section along a named straight edge with expression dimensions. Segment expressions see edge_length,parent_length,parent_width,thickness and document parameters. Curved/conical/stretched paths and general lofted bends remain unsupported; a generic loft is not developed-sheet evidence."));
        rules.arr.push_back(V::makeStr("Corner source uses panel,corner:0..3 and kind:relief|trim with shape:rectangular,width,height or shape:round,radius; break uses distance. closure uses panel,target,side:start|end,gap:positive,from for a connected terminal side extension toward a perpendicular target, with finite gap measured and bend regions open. Closure adds material but no weld. rip:{id,panel,edge,station,width,depth} makes a partial straight-edge open notch inside the span; split panels, curved bend bands and closed-shell seam ripping reject."));
        rules.arr.push_back(V::makeStr("Tab and paired slot: tab:{id,panel,edge,station,width,length,slot_panel,slot_x,slot_y,clearance:positive}. A real tab and a different-panel rectangular slot regenerate; slot width=tab_width+2*clearance, slot height=thickness+2*clearance. The receipt sets assembly_fit_verified:false; no implicit positioning, assembled contact, laser kerf or manufacturing fit is certified. Corner kinds should be replaced by atomic remove/add when their required fields change."));
        rules.arr.push_back(V::makeStr("sheet.bend_table.set{id,table:{interpolation:exact,entries:[{thickness,inner_radius,angle:unsigned,bend_allowance}]}} changes actual flat development and independent refold, rather than adding unused metadata. Each bend must match one row at the fixed 1e-9 comparison; duplicate/missing keys, interpolation/extrapolation and conflicting segment K reject. Effective K=(allowance/angle_radians-inner_radius)/thickness must be 0..1; inspect bend_allowance_source:authored_exact_bend_table. This is declared allowance input, not material/shop calibration. sheet.bend_table.remove{id} removes the authority explicitly."));
        rules.arr.push_back(V::makeStr("Inspect exact connected formed/flat solids, blank/refold evidence, openings and every advanced operation receipt before export. Cross break, gusset, welded corners, general forming, curved/conical sweep, lofted bends, imported closed-shell rip, bend-trajectory collision and production qualification remain open. A visible tool name or valid preview alone is not delivery of those domains."));
        r.set("rules",rules);r.set("advanced_sheet_contract",V::makeStr("docs/ADVANCED_SHEETMETAL_022B.md"));
        V example;arkjson::parse(R"({"commands":[{"op":"sheet.create","name":"Miter sample","p":{"width":100,"thickness":2,"k_factor":0.5},"base":{"id":"base","length":120}},{"op":"sheet.miter.add","id":"Miter sample","miter":{"id":"rim","parent":"base","edges":["u_max","v_max"],"gap":1,"profile":[{"length":35,"angle":90,"inner_radius":3},{"length":12,"angle":-90,"inner_radius":3}]}}]})",example);example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_advanced_sheet",example);
    }
    r.set("prepared_refresh",V::makeStr("After an independent peer commit, retain your candidate_id, read the current revision and explicitly call doc_preview{candidate_id,expected_revision:current}. Supported feature.add/edit recipes with unchanged targets, transitive inputs and authored context can produce a new candidate without resending commands. Inspect the new recipe/IDs and apply receipt; allocation may change. Old apply payloads still reject, and refresh never commits automatically. Conflicts, checks or unsupported recipes require a fresh explicit preview. Team candidates remain owned by their originating role. Cache custody is bounded by count, size and expiry; project replacement or undo/redo clears it. See docs/CANDIDATE_REFRESH_031B.md."));
    r.set("drawing_usage",V::makeStr("usage_info reads persisted provider-reported drawing token receipts. usage_record accepts real external provider usage under an idempotent receipt ID; do not invent counts for external MCP calls. Usage has a separate metadata serial and survives geometry undo/redo. Empty or incomplete external usage remains explicitly unknown."));
    if(topic!="overview")r.set("targeted_reads",V::makeStr("doc_info{detail:digest} is the compact inventory; with known_fingerprints it returns only changed rows and removed keys. After the initial inventory, doc_info{detail:design,ids:[feature id or unique name],sections:[features,sketches,assembly,materials,parameters]} returns only requested sections. ids default to features only. Sketches/assembly/materials select direct feature associations; parameters stay document-wide. partial/scope/section_scopes/total_counts make selection explicit. Use sketch_inspect entity or native_inspect for exact detail; avoid repeating full doc_get when a selected design read answers the question."));
    if(topic=="overview")r.set("object_context_workflow",V::makeStr("For a task on an existing object, prefer object_context with node/copy from the user's selected occurrence or ids for a definition. A selection is an explicit target, not a guess from a screenshot. Without a selection, query names/types and inspect candidate relationships; do not claim a text match proves mechanical function. Read the relevant dependencies, sketches and mates before editing. Retain returned fingerprints and use known_fingerprints on subsequent reads to omit unchanged object bodies. Fingerprints detect content changes; IDs identify objects, and expected_revision still protects every write. Never substitute a fingerprint for semantic face/edge references or geometric validity. snapshot returns real PNG image evidence with revision and target IDs; internal connectors deliver those pixels to vision-capable models. A file path alone is never proof of seeing an image."));
    if(topic=="assembly"||topic=="motion")r.set("limited_joints",V::makeStr("Use type prismatic for a pneumatic cylinder or slider: reference +Z is the stroke axis, the relative orientation remains locked, and only axial translation is free. Ground the cylinder body, place the rod using real attachment frames, and add limits:{min:0,max:stroke} in mm. Revolute limits use degrees. Both bounds accept saved parameter expressions; limits:null removes them. The coordinate is signed B relative to A, not accumulated mouse distance. A bounded revolute interval spans less than 360 degrees; multi-turn angular state is unsupported. Preview with assembly_info.drive before assembly.drive at the current expected_revision. Out-of-range API requests reject atomically; the mouse stops at the authored limit. Rigid attachments follow the moving side. Grounded closed linkages and supported transmission boundaries use constrained continuation; inspect solver, continuation_steps, diagnostics and coupling_residuals. The verified reference domain includes planar four-bar and slider-crank mechanisms. Singular, unsatisfied, ungrounded and out-of-limit paths reject atomically; collision and forces remain unqualified. New joint semantics require document version31."));
    if(topic=="overview")r.set("visual_feedback",V::makeStr("For an existing-object task, resolve IDs with object_context, then request snapshot{id or node,view:iso|front|right|top,expected_revision}. A Studio snapshot{view:viewport,expected_revision} renders the current GPU scene offscreen, including bloom, camera/selection and uncommitted previews. It works while Studio is minimized or chat covers the viewport, preserves window state and excludes UI chrome; do not ask the user to restore Studio for this capture. Named snapshots are software renders of the selected display mesh; neither is B-rep evidence. Obtain before/after views when visual form matters, but do not repeatedly fetch unchanged images. The connector retains only recent pixels and keeps metadata; request fresh images when necessary. Unsupported vision models reject rather than silently claiming to see pixels."));
    if(topic=="frames"||topic=="tube"||topic=="automation")r.set("failure_workflow",V::makeStr("Before risky edits use doc_preview{expected_revision,commands,detail:changes}; inspect changed_feature_ids/end_fit_evidence and snapshot{candidate_id,expected_revision,view:iso} before committing its apply payload. Errors retain a local failure_id. failure_info{id} shows the exact rejected recipe/cause; failure_replay{id,expected_revision} evaluates its immutable baseline in isolation, never edits the current drawing. failure_export{id,path} is an explicit local private-design bundle for reproduction after restart; never export or share it without a relevant user request. Repeated identical failures are identified despite metadata/key-order changes; inspect and correct the cause rather than retrying unchanged commands."));
