        V dimensionCreate,dimensionEdit;arkjson::parse(R"JSON({"commands":[{"op":"param.set","name":"profile_radius_mm","expr":"7"},{"op":"sketch.set","name":"Dimensioned circle","sketch":{"plane":"XY","entities":[{"kind":"circle","name":"ring","dof":[0,0,"profile_radius_mm"]}],"constraints":[]}}]})JSON",dimensionCreate);arkjson::parse(R"JSON({"commands":[{"op":"param.set","name":"profile_radius_mm","expr":"9"}]})JSON",dimensionEdit);
